	@Test
	@Timeout(30)
	void repeatedTopLevelScopesDoNotAllocateAnEntryPerSubplan(@TempDir Path tempDir)
			throws IOException, InterruptedException {
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		assertThat(classpath).isNotBlank();
		Path childOutput = tempDir.resolve("scope-allocation-child.txt");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		ProcessBuilder builder = new ProcessBuilder(java, "-ea", "-cp", classpath,
				NativeKernelSubplanAllocationProbe.class.getName(), "100000", "20000", "100000");
		builder.redirectErrorStream(true);
		builder.redirectOutput(childOutput.toFile());
		builder.environment().remove("JAVA_TOOL_OPTIONS");
		builder.environment().remove("_JAVA_OPTIONS");
		builder.environment().remove("JDK_JAVA_OPTIONS");

		Process child = builder.start();
		try {
			if (!child.waitFor(15, TimeUnit.SECONDS)) {
				terminateOwnedChild(child);
				throw new AssertionError(
						"clean allocation-measurement child exceeded its 15-second deadlock guard; output: "
								+ Files.readString(childOutput, StandardCharsets.UTF_8));
			}
			String output = Files.readString(childOutput, StandardCharsets.UTF_8);
			System.out.print(output);
			assumeTrue(!output.contains("UNSUPPORTED_THREAD_ALLOCATED_MEMORY"),
					"HotSpot per-thread allocation accounting is required for this regression: " + output);
			assertThat(child.exitValue()).as("clean allocation-measurement child output: %s", output).isZero();
			String result = output.lines()
					.filter(line -> line.startsWith("KERNEL_SUBPLAN_SCOPE_ALLOCATION "))
					.findFirst()
					.orElseThrow(() -> new AssertionError("child did not emit allocation results: " + output));
			assertThat(result).contains("mismatch=0", "forced=ok", "agents=0");
			String marginal = List.of(result.split("\\s+"))
					.stream()
					.filter(field -> field.startsWith("marginal="))
					.findFirst()
					.orElseThrow(() -> new AssertionError("child omitted marginal allocation result: " + result));
			long marginalBytes = Long.parseLong(marginal.substring("marginal=".length(), marginal.length() - 1));
			assertThat(marginalBytes)
					.as("additional top-level lexical callbacks must reuse their inactive ThreadLocal entry")
					.isLessThan(16_384L);
		} finally {
			if (child.isAlive()) {
				terminateOwnedChild(child);
			}
		}
	}

