	private static void terminateOwnedChild(Process child) throws InterruptedException {
		child.destroy();
		if (!child.waitFor(2, TimeUnit.SECONDS)) {
			child.destroyForcibly();
			if (!child.waitFor(2, TimeUnit.SECONDS)) {
				throw new AssertionError("owned allocation-measurement child survived forced termination");
			}
		}
	}

