final class NativeKernelSubplanAllocationProbe {
	private static final String FORCE = LmdbNativeAttemptMetrics.PATH_NESTED_LOOP;

	private NativeKernelSubplanAllocationProbe() {
	}

	public static void main(String[] args) {
		if (args.length != 3) {
			throw new IllegalArgumentException("expected preflight, short-batch, and long-batch cycle counts");
		}
		if (!(ManagementFactory.getThreadMXBean() instanceof ThreadMXBean bean)
				|| !bean.isThreadAllocatedMemorySupported()) {
			System.out.println("UNSUPPORTED_THREAD_ALLOCATED_MEMORY");
			return;
		}
		boolean restoreAllocationSetting = !bean.isThreadAllocatedMemoryEnabled();
		if (restoreAllocationSetting) {
			bean.setThreadAllocatedMemoryEnabled(true);
		}
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"SELECT * WHERE { ?s ?p ?o }", Query.QueryType.TUPLE, FORCE);
		try {
			boolean agentsAbsent = ManagementFactory.getRuntimeMXBean()
					.getInputArguments()
					.stream()
					.noneMatch(argument -> argument.startsWith("-javaagent:")
							|| argument.startsWith("-agentlib:")
							|| argument.startsWith("-agentpath:"));
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null,
					null,
					0L, new EvaluationStatistics(), false);
			boolean initiallyForced = FORCE.equals(strategy.forcedExecutionStrategyName())
					&& FORCE.equals(LmdbNativeEvaluationStrategy.forcedExecutionStrategyForCurrentThread());
			int[] preflightMismatches = new int[1];
			int preflightCycles = Integer.parseInt(args[0]);
			preflightMismatches[0] = runScopeCycles(strategy, preflightCycles);
			int[] shortMismatches = new int[1];
			long shortBatch = allocatedBytes(bean, strategy, Integer.parseInt(args[1]), shortMismatches);
			int[] longMismatches = new int[1];
			long longBatch = allocatedBytes(bean, strategy, Integer.parseInt(args[2]), longMismatches);
			long marginalBytes = longBatch - shortBatch;
			boolean forcedAfter = FORCE.equals(strategy.forcedExecutionStrategyName())
					&& FORCE.equals(LmdbNativeEvaluationStrategy.forcedExecutionStrategyForCurrentThread());
			System.out.printf(
					"KERNEL_SUBPLAN_SCOPE_ALLOCATION short=%dB long=%dB marginal=%dB mismatch=%d forced=%s agents=%d%n",
					shortBatch, longBatch, marginalBytes,
					preflightMismatches[0] + shortMismatches[0] + longMismatches[0],
					initiallyForced && forcedAfter ? "ok" : "bad", agentsAbsent ? 0 : 1);
			if (preflightMismatches[0] != 0 || shortMismatches[0] != 0 || longMismatches[0] != 0
					|| !initiallyForced || !forcedAfter || !agentsAbsent) {
				throw new IllegalStateException(
						"clean child did not preserve the forced-scope allocation preconditions");
			}
		} finally {
			SlowQueryContextHolder.restore(previous);
			if (restoreAllocationSetting) {
				bean.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static long allocatedBytes(ThreadMXBean bean, LmdbNativeEvaluationStrategy strategy, int cycles,
			int[] mismatches) {
		long thread = Thread.currentThread().threadId();
		long before = bean.getThreadAllocatedBytes(thread);
		mismatches[0] = runScopeCycles(strategy, cycles);
		return bean.getThreadAllocatedBytes(thread) - before;
	}

	private static int runScopeCycles(LmdbNativeEvaluationStrategy strategy, int cycles) {
		int mismatches = 0;
		for (int i = 0; i < cycles; i++) {
			boolean nested = LmdbNativeEvaluationStrategy.enterKernelSubplan();
			if (nested || strategy.forcedExecutionStrategyName() != null
					|| LmdbNativeEvaluationStrategy.forcedExecutionStrategyForCurrentThread() != null) {
				mismatches++;
			}
			LmdbNativeEvaluationStrategy.leaveKernelSubplan(nested);
			if (!FORCE.equals(strategy.forcedExecutionStrategyName())
					|| !FORCE.equals(LmdbNativeEvaluationStrategy.forcedExecutionStrategyForCurrentThread())) {
				mismatches++;
			}
		}
		return mismatches;
	}

	private static final class EmptyTripleSource implements TripleSource {
		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new EmptyIteration<>();
		}
	}
}
